-- DROP & CREATE TABLE FOR `product_variants`
DROP TABLE IF EXISTS `product_variants`;
CREATE TABLE `product_variants` (
  `id` varchar(36) NOT NULL,
  `product_id` varchar(36) NOT NULL,
  `variant_sku` varchar(50) NOT NULL,
  `variant_name` varchar(150) NOT NULL,
  `pack_size_kg` decimal(12,4) NOT NULL,
  `selling_price_per_kg` decimal(15,2) NOT NULL,
  `selling_price_usd_per_kg` decimal(15,2) DEFAULT NULL,
  `selling_price_per_unit` decimal(15,2) GENERATED ALWAYS AS (`selling_price_per_kg` * `pack_size_kg`) STORED,
  `min_stock_kg` decimal(12,4) DEFAULT 0.0000,
  `min_stock_units` int(11) GENERATED ALWAYS AS (round(`min_stock_kg` / `pack_size_kg`,0)) STORED,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `variant_sku` (`variant_sku`),
  KEY `idx_variants_product_id` (`product_id`,`is_active`),
  KEY `idx_variants_sku` (`variant_sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

