-- DROP & CREATE TABLE FOR `products`
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` varchar(36) NOT NULL,
  `sku` varchar(50) NOT NULL,
  `name` varchar(150) NOT NULL,
  `applications` text DEFAULT NULL,
  `application` varchar(50) DEFAULT 'Fine Fragrance',
  `fragrance_family` varchar(50) DEFAULT 'Fine Fragrance',
  `top_notes` text DEFAULT NULL,
  `middle_notes` text DEFAULT NULL,
  `base_notes` text DEFAULT NULL,
  `density` decimal(6,4) DEFAULT 1.0000,
  `is_active` tinyint(1) DEFAULT 1,
  `image_url` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `pack_sizes` text DEFAULT NULL,
  `variant_prices` text DEFAULT NULL,
  `variant_names` text DEFAULT NULL,
  `variant_skus` text DEFAULT NULL,
  `selling_price_usd_per_kg` decimal(15,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sku` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

