-- DROP & CREATE TABLE FOR `sales_orders`
DROP TABLE IF EXISTS `sales_orders`;
CREATE TABLE `sales_orders` (
  `id` varchar(36) NOT NULL,
  `so_number` varchar(50) NOT NULL,
  `customer_id` varchar(36) NOT NULL,
  `courier_id` varchar(36) DEFAULT NULL,
  `status` varchar(30) DEFAULT 'PENDING_APPROVAL',
  `payment_method` varchar(20) NOT NULL,
  `total_goods_amount` decimal(15,2) NOT NULL,
  `grand_total` decimal(15,2) NOT NULL,
  `order_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `delivered_date` timestamp NULL DEFAULT NULL,
  `surat_jalan_number` varchar(100) DEFAULT NULL,
  `courier_name` varchar(100) DEFAULT NULL,
  `received_by` varchar(100) DEFAULT NULL,
  `received_photo` longtext DEFAULT NULL,
  `received_signature` longtext DEFAULT NULL,
  `cancellation_reason` text DEFAULT NULL,
  `cancelled_at` varchar(100) DEFAULT NULL,
  `cancelled_by` varchar(100) DEFAULT NULL,
  `shipping_type` enum('FRANCO','LOCO') DEFAULT 'FRANCO',
  `shipping_cost` decimal(15,2) DEFAULT 0.00,
  PRIMARY KEY (`id`),
  UNIQUE KEY `so_number` (`so_number`),
  KEY `customer_id` (`customer_id`),
  KEY `courier_id` (`courier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

